#pragma once

#include <dlfcn.h>
#include <memory>
#include <string>
#include <string_view>
#include <boost/core/noncopyable.hpp>


namespace DB
{

/** Allows to open a dynamic library and get a pointer to a function from it.
  * Used only by library-bridge. Dynamic library loading should not be present
  *  in the main clickhouse binaries.
  */
class SharedLibrary : private boost::noncopyable
{
public:
    SharedLibrary(std::string_view path, int flags = RTLD_LAZY);

    ~SharedLibrary();

    template <typename Func>
    Func get(std::string_view name)
    {
        return reinterpret_cast<Func>(getImpl(name, false));
    }

    template <typename Func>
    Func tryGet(std::string_view name)
    {
        return reinterpret_cast<Func>(getImpl(name, true));
    }

private:
    void * handle = nullptr;

    void * getImpl(std::string_view name, bool no_throw);
};

using SharedLibraryPtr = std::shared_ptr<SharedLibrary>;

}

#include "SharedLibrary.h"
#include <string>
#include <base/phdr_cache.h>
#include <Common/Exception.h>


namespace DB
{
namespace ErrorCodes
{
    extern const int CANNOT_DLOPEN;
    extern const int CANNOT_DLSYM;
}

SharedLibrary::SharedLibrary(std::string_view path, int flags)
{
    handle = dlopen(path.data(), flags);
    if (!handle)
        throw Exception(ErrorCodes::CANNOT_DLOPEN, "Cannot dlopen: ({})", dlerror());

    updatePHDRCache();

    /// NOTE: race condition exists when loading multiple shared libraries concurrently.
    /// We don't care (or add global mutex for this method).
}

SharedLibrary::~SharedLibrary()
{
    if (handle && dlclose(handle))
        std::terminate();
}

void * SharedLibrary::getImpl(std::string_view name, bool no_throw)
{
    dlerror();

    auto * res = dlsym(handle, name.data());

    if (char * error = dlerror())
    {
        if (no_throw)
            return nullptr;

        throw Exception(ErrorCodes::CANNOT_DLSYM, "Cannot dlsym: ({})", error);
    }

    return res;
}
}

